-- โรงอาหารหอหญิง: the six stalls and their menus, transcribed from ร้านหอหญิง.pdf (27 ก.ย. 69).
-- Store photos are the stall photos in that PDF (frontend/static/stores/female-dorm-NN.webp); dishes have none yet.
-- Left out until the stalls give an exact price: menus priced only as a range in the PDF
-- (see PLAN.md). Stores start hidden and closed; the team shows them from the console.
-- Safe to run twice: existing rows are kept.
begin;
select public.log_admin('STORE_CREATED', 'store', 'female-dorm-01', 'Mr. Moustache', '{"source": "ร้านหอหญิง.pdf"}'::jsonb) where not exists (select 1 from public.admin_log where action = 'STORE_CREATED' and target_id = 'female-dorm-01');
select public.log_admin('STORE_CREATED', 'store', 'female-dorm-02', 'ร้านแม่น้องพั๊นซ์', '{"source": "ร้านหอหญิง.pdf"}'::jsonb) where not exists (select 1 from public.admin_log where action = 'STORE_CREATED' and target_id = 'female-dorm-02');
select public.log_admin('STORE_CREATED', 'store', 'female-dorm-03', 'ข้าวแกงย่าสมัย', '{"source": "ร้านหอหญิง.pdf"}'::jsonb) where not exists (select 1 from public.admin_log where action = 'STORE_CREATED' and target_id = 'female-dorm-03');
select public.log_admin('STORE_CREATED', 'store', 'female-dorm-04', 'ลุงชิคกี้', '{"source": "ร้านหอหญิง.pdf"}'::jsonb) where not exists (select 1 from public.admin_log where action = 'STORE_CREATED' and target_id = 'female-dorm-04');
select public.log_admin('STORE_CREATED', 'store', 'female-dorm-05', 'ร้านข้าวแกงปักษ์ใต้ ต.ปากพนัง (นครศรีฯ)', '{"source": "ร้านหอหญิง.pdf"}'::jsonb) where not exists (select 1 from public.admin_log where action = 'STORE_CREATED' and target_id = 'female-dorm-05');
select public.log_admin('STORE_CREATED', 'store', 'female-dorm-06', 'ร้านน้ำหอหญิง', '{"source": "ร้านหอหญิง.pdf"}'::jsonb) where not exists (select 1 from public.admin_log where action = 'STORE_CREATED' and target_id = 'female-dorm-06');
commit;
